[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* ===== Reset & Variables ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #003B95;
  --navy-dark: #002670;
  --blue: #006CE4;
  --blue-light: #e8f2ff;
  --gold: #FFB700;
