.hero h1 { font-size: 38px; font-weight: 800; margin-bottom: 8px; letter-spacing: -0.5px; }
.hero .subtitle { font-size: 18px; opacity: 0.9; margin-bottom: 32px; font-weight: 400; }

/* Search Forms */
.search-form {
