}
.deal-card-body { padding: 14px 16px; }
.deal-card-body h4 { font-size: 14px; font-weight: 600; color: var(--text-primary); margin-bottom: 2px; }
.deal-card-body .location { font-size: 12px; color: var(--text-secondary); margin-bottom: 6px; }
.deal-card-body .rating { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; margin-bottom: 8px; }
.deal-card-body .rating-badge {
  background: var(--navy); color: var(--white); padding: 2px 7px;
  border-radius: 4px 4px 4px 0; font-size: 12px; font-weight: 700;
}
.deal-card-body .duration { font-size: 12px; color: var(--text-secondary); margin-bottom: 4px; }
.deal-card-body .prices { display: flex; align-items: baseline; gap: 8px; }
.deal-card-body .price-original { font-size: 13px; color: var(--text-secondary); text-decoration: line-through; }
.deal-card-body .price-sale { font-size: 18px; font-weight: 700; color: var(--text-primary); }

/* ===== Homes Guests Love ===== */
.homes-scroll {
  display: flex; gap: 20px; overflow-x: auto;
  -ms-overflow-style: none; scrollbar-width: none; padding: 4px 0;
}
.homes-scroll::-webkit-scrollbar { display: none; }
.homes-scroll .property-card { flex: 0 0 260px; }
.homes-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
.homes-header a { font-size: 14px; font-weight: 600; }

/* ===== Loyalty CTA ===== */
.loyalty-cta {
  background: linear-gradient(135deg, var(--navy) 0%, var(--blue) 100%);
  border-radius: var(--radius-xl); padding: 48px; color: var(--white);
  display: flex; align-items: center; justify-content: space-between; gap: 40px;
}
.loyalty-cta h2 { font-size: 28px; font-weight: 700; margin-bottom: 4px; }
.loyalty-cta .sub { font-size: 16px; font-weight: 500; opacity: 0.9; margin-bottom: 12px; }
.loyalty-cta p { font-size: 14px; opacity: 0.85; max-width: 500px; }
.loyalty-cta-actions { display: flex; gap: 12px; flex-shrink: 0; }

/* ===== Popular Links ===== */
.popular-links-content ul {
  list-style: none; display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 8px;
}
.popular-links-content a {
  font-size: 14px; color: var(--text-body); padding: 4px 0;
  display: inline-block;
}
.popular-links-content a:hover { color: var(--blue); }

/* ===== Benefits ===== */
.benefits-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.benefit-card {
  padding: 32px 24px; border-radius: var(--radius-md);
  border: 1px solid var(--gray-200); text-align: center;
}
.benefit-card i { font-size: 32px; color: var(--blue); margin-bottom: 16px; display: block; }
.benefit-card h4 { font-size: 16px; font-weight: 600; margin-bottom: 8px; color: var(--text-primary); }
.benefit-card p { font-size: 14px; color: var(--text-secondary); }

/* ===== Rental Companies ===== */
.rental-logos {
  display: flex; flex-wrap: wrap; gap: 24px; align-items: center; justify-content: center;
}
.rental-logo {
  padding: 20px 32px; border-radius: var(--radius-md);
  border: 1px solid var(--gray-200); font-size: 20px; font-weight: 700;
  color: var(--gray-700); min-width: 140px; text-align: center;
}

/* ===== FAQ Accordion ===== */
.faq-list { max-width: 800px; }
.faq-item {
  border: 1px solid var(--gray-200); border-radius: var(--radius-md);
  margin-bottom: 8px; overflow: hidden;
}
.faq-question {
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px 20px; background: var(--white); border: none;
  width: 100%; text-align: left; font-size: 15px; font-weight: 600;
  color: var(--text-primary); cursor: pointer; transition: background 0.2s;
}
.faq-question:hover { background: var(--gray-50); }
.faq-question i { transition: transform 0.3s; font-size: 18px; color: var(--gray-600); }
.faq-item.open .faq-question i { transform: rotate(180deg); }
.faq-answer {
  max-height: 0; overflow: hidden; transition: max-height 0.3s ease, padding 0.3s ease;
  padding: 0 20px;
}
.faq-item.open .faq-answer { max-height: 200px; padding: 0 20px 18px; }
.faq-answer p { font-size: 14px; color: var(--text-secondary); line-height: 1.6; }

/* ===== Credit Card Promo ===== */
.credit-promo {
  background: linear-gradient(135deg, #1A1A2E 0%, var(--navy) 100%);
  border-radius: var(--radius-xl); padding: 40px; color: var(--white);
  display: flex; align-items: center; justify-content: space-between; gap: 32px;
}
.credit-promo h3 { font-size: 22px; font-weight: 700; margin-bottom: 8px; }
.credit-promo p { font-size: 14px; opacity: 0.85; max-width: 450px; }

/* ===== Account CTA ===== */
.account-cta {
  background: var(--blue-light); border-radius: var(--radius-xl);
  padding: 48px; text-align: center;
}
.account-cta h2 { font-size: 28px; font-weight: 700; margin-bottom: 8px; color: var(--text-primary); }
.account-cta .subtitle { font-size: 16px; color: var(--text-secondary); margin-bottom: 8px; }
.account-cta p { font-size: 14px; color: var(--text-secondary); margin-bottom: 20px; max-width: 400px; margin-left: auto; margin-right: auto; }
.account-cta-actions { display: flex; gap: 12px; justify-content: center; }

/* ===== Recommended Attractions ===== */
.attractions-list { display: flex; flex-direction: column; gap: 12px; }
.attraction-item {
  display: flex; gap: 16px; padding: 16px; border-radius: var(--radius-md);
  border: 1px solid var(--gray-200); transition: all 0.2s; cursor: pointer;
}
.attraction-item:hover { border-color: var(--blue); box-shadow: var(--shadow-sm); }
.attraction-item-img {
  width: 80px; height: 80px; border-radius: var(--radius-sm);
  background: var(--gray-200); flex-shrink: 0; overflow: hidden;
}
.attraction-item-img img { width: 100%; height: 100%; object-fit: cover; }
.attraction-item-body h4 { font-size: 14px; font-weight: 600; color: var(--text-primary); margin-bottom: 4px; }
.attraction-item-body p { font-size: 13px; color: var(--text-secondary); }
.attraction-item-body .price { font-size: 14px; font-weight: 700; color: var(--blue); margin-top: 4px; }

/* ===== Nearby Destinations ===== */
.nearby-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 16px;
}
.nearby-card {
  border-radius: var(--radius-md); overflow: hidden; position: relative;
  aspect-ratio: 3/2; cursor: pointer; transition: transform 0.2s;
}
.nearby-card:hover { transform: translateY(-2px); }
.nearby-card img { width: 100%; height: 100%; object-fit: cover; }
.nearby-card .overlay {
  position: absolute; inset: 0;
  background: linear-gradient(transparent 30%, rgba(0,0,0,0.65));
  display: flex; flex-direction: column; justify-content: flex-end; padding: 14px;
  color: var(--white);
}
.nearby-card h4 { font-size: 15px; font-weight: 600; }
.nearby-card span { font-size: 12px; opacity: 0.85; }

/* ===== Explore Cities (Attractions) ===== */
.explore-cities-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 16px;
}
.city-card {
  padding: 16px; border-radius: var(--radius-md); border: 1px solid var(--gray-200);
  transition: all 0.2s; cursor: pointer;
}
.city-card:hover { border-color: var(--blue); box-shadow: var(--shadow-sm); }
.city-card h4 { font-size: 15px; font-weight: 600; color: var(--text-primary); margin-bottom: 4px; }
.city-card span { font-size: 13px; color: var(--text-secondary); }

/* ===== Popular Things To Do ===== */
.things-list { columns: 2; column-gap: 24px; }
.things-list a {
  display: block; padding: 6px 0; font-size: 14px; color: var(--text-body);
  break-inside: avoid;
}
.things-list a:hover { color: var(--blue); }

/* ===== Car Rental Destinations ===== */
.car-dest-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); gap: 16px;
}
.car-dest-card {
  padding: 20px; border-radius: var(--radius-md); border: 1px solid var(--gray-200);
  transition: all 0.2s;
}
.car-dest-card:hover { border-color: var(--blue); box-shadow: var(--shadow-sm); }
.car-dest-card h4 { font-size: 16px; font-weight: 600; color: var(--text-primary); margin-bottom: 4px; }
.car-dest-card .locations { font-size: 13px; color: var(--text-secondary); margin-bottom: 6px; }
.car-dest-card .price { font-size: 15px; font-weight: 700; color: var(--blue); }

/* ===== Package Destinations ===== */
.pkg-dest-grid {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 20px;
}
.pkg-dest-card {
  border-radius: var(--radius-md); overflow: hidden; position: relative;
  aspect-ratio: 16/10; cursor: pointer; transition: transform 0.2s;
}
.pkg-dest-card:hover { transform: translateY(-2px); }
.pkg-dest-card img { width: 100%; height: 100%; object-fit: cover; }
.pkg-dest-card .overlay {
  position: absolute; inset: 0;
  background: linear-gradient(transparent 30%, rgba(0,0,0,0.7));
  display: flex; flex-direction: column; justify-content: flex-end; padding: 20px;
  color: var(--white);
}
.pkg-dest-card h4 { font-size: 18px; font-weight: 700; margin-bottom: 2px; }
.pkg-dest-card .country { font-size: 13px; opacity: 0.85; margin-bottom: 4px; }
.pkg-dest-card .props { font-size: 13px; opacity: 0.8; }

/* ===== Footer ===== */
.site-footer {
  background: var(--gray-900); color: rgba(255,255,255,0.75); padding: 48px 0 32px;
}
.footer-grid {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px; margin-bottom: 40px;
}
.footer-col h5 { color: var(--white); font-size: 14px; font-weight: 600; margin-bottom: 14px; }
.footer-col a {
  display: block; font-size: 13px; color: rgba(255,255,255,0.65);
  padding: 3px 0; transition: color 0.2s;
}
.footer-col a:hover { color: var(--white); text-decoration: none; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px;
  font-size: 13px; color: rgba(255,255,255,0.5); line-height: 1.6;
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .trust-badges { grid-template-columns: repeat(2, 1fr); }
  .offers-grid { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .loyalty-cta { flex-direction: column; text-align: center; padding: 36px; }
  .loyalty-cta p { max-width: 100%; }
  .credit-promo { flex-direction: column; text-align: center; }
  .credit-promo p { max-width: 100%; }
}

@media (max-width: 768px) {
  .hero h1 { font-size: 28px; }
  .hero .subtitle { font-size: 15px; }
  .search-form { flex-direction: column; border-radius: var(--radius-md); }
  .search-form-row { flex-direction: column; }
  .section { padding: 40px 0; }
  .section-header h2 { font-size: 22px; }
  .trust-badges { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .dest-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: repeat(2, 1fr); }
  .car-dest-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .things-list { columns: 1; }
  .header-nav { display: none; }
  .header-inner { flex-wrap: wrap; height: auto; padding: 12px 24px; gap: 8px; }
  .header-nav-mobile { display: flex; width: 100%; gap: 0; overflow-x: auto; }
  .package-radios { gap: 12px; }
  .loyalty-cta { padding: 28px; }
  .loyalty-cta h2 { font-size: 22px; }
  .popular-links-content ul { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 24px; }
  .container { padding: 0 16px; }
  .dest-grid { grid-template-columns: 1fr; }
  .deals-grid { grid-template-columns: 1fr; }
  .nearby-grid { grid-template-columns: repeat(2, 1fr); }
  .explore-cities-grid { grid-template-columns: repeat(2, 1fr); }
  .car-dest-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .popular-links-content ul { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(2, 1fr); }
  .trip-planner-destinations { grid-template-columns: repeat(2, 1fr); }
}

/* ===== Mobile Nav ===== */
.header-nav-mobile { display: none; }
@media (max-width: 768px) {
  .header-nav { display: none; }
  .header-nav-mobile {
    display: flex; width: 100%; gap: 0; overflow-x: auto;
    -ms-overflow-style: none; scrollbar-width: none;
  }
  .header-nav-mobile::-webkit-scrollbar { display: none; }
  .header-nav-mobile a {
    color: rgba(255,255,255,0.85); font-size: 13px; font-weight: 500;
    padding: 8px 12px; white-space: nowrap;
  }
  .header-nav-mobile a.active { color: var(--white); border-bottom: 2px solid var(--gold); }
}
